handlers.expression:
() => {
                const parsed = new Date(slot);
                if (!Number.isFinite(parsed.getTime())) return;
                void mutate(
                  `/api/agent/matchmaking/requests/${encodeURIComponent(request.requestId)}/slots`,
                  {
                    method: "POST",
                    body: JSON.stringify({ slots: [parsed.toISOString()] }),
                  },
                );
              }

